def P(one, other):
    return {'one': one, 'other': other}


def S(one, other):
    """Spanish and Portuguese: 'many' (a million and up) reads like 'other'."""
    return {'one': one, 'other': other, 'many': other}


def A(zero, one, two, few, many, other):
    return {'zero': zero, 'one': one, 'two': two, 'few': few, 'many': many, 'other': other}


